// Map PLC tags (msg.payload) to the shared Telemetry schema (plan §6.1).
const LINE = 'L1', STATION = 'S1';
const t = msg.payload || {};

// derive state from PLC booleans/tags
let state = 'idle';
if (t.down) state = 'down';
else if (t.blocked) state = 'blocked';
else if (t.running) state = 'running';
else state = 'idle';

msg.topic = `factory/${LINE}/${STATION}/telemetry`;
msg.payload = {
  ts: new Date().toISOString().replace(/\.\d+Z$/, 'Z'),
  line_id: LINE,
  station_id: STATION,
  current_a: Number(t.amps ?? 0),
  part_present: Boolean(t.partPresent ?? false),
  part_count: Number(t.partCount ?? 0),
  cycle_time_s: t.cycle_s != null ? Number(t.cycle_s) : null,
  state: state
};
return msg;
